import com.amazonaws.services.s3.model.S3ObjectInputStream;
import com.amazonaws.client.builder.AwsClientBuilder.EndpointConfiguration;
import com.amazonaws.auth.profile.ProfileCredentialsProvider;
import com.amazonaws.services.texttract.AmazonTexttract;
import com.amazonaws.services.texttract.AmazonTexttractClientBuilder;
import com.amazonaws.services.texttract.model.Block;
import com.amazonaws.services.texttract.model.BoundingBox;
import com.amazonaws.services.texttract.model.DetectDocumentTextRequest;
import com.amazonaws.services.texttract.model.DetectDocumentTextResult;
import com.amazonaws.services.texttract.model.Document;
import com.amazonaws.services.texttract.model.S3Object;
import com.amazonaws.services.texttract.model.Point;
import com.amazonaws.services.texttract.model.Relationship;

public class DocumentText extends JPanel {

    private static final long serialVersionUID = 1L;

    BufferedImage image;
    DetectDocumentTextResult result;

    public DocumentText(DetectDocumentTextResult documentResult, BufferedImage bufImage) throws Exception {
        super();
        result = documentResult; // Results of text detection.
        image = bufImage; // The image containing the document.
    }

    // Draws the image and text bounding box.
    public void paintComponent(Graphics g) {

        int height = image.getHeight(this);
        int width = image.getWidth(this);

        Graphics2D g2d = (Graphics2D) g; // Create a Java2D version of g.

        // Draw the image.
        g2d.drawImage(image, 0, 0, image.getWidth(this), image.getHeight(this), this);

        // Iterate through blocks and display polygons around lines of detected text.
    }
```

